/*
 * Runs the FAMI-C example ROMs on the documentation site.
 *
 * The ROMs under `roms/` and the JSNES build under `vendor/jsnes/` are both
 * generated by `tools/build_pages.py`, so the page needs no bundler and no
 * network access beyond its own origin.
 */

import { Browser, Controller } from "./vendor/jsnes/index.js";

const PAD = {
  a: Controller.BUTTON_A,
  b: Controller.BUTTON_B,
  select: Controller.BUTTON_SELECT,
  start: Controller.BUTTON_START,
  up: Controller.BUTTON_UP,
  down: Controller.BUTTON_DOWN,
  left: Controller.BUTTON_LEFT,
  right: Controller.BUTTON_RIGHT,
};

const PLAYER_ONE = 1;
const MAX_VOLUME = 256;

const root = document.querySelector("[data-emulator]");
if (root) {
  setUpEmulator(root);
}

function setUpEmulator(root) {
  const stage = root.querySelector("[data-role=stage]");
  const overlay = root.querySelector("[data-role=overlay]");
  const status = root.querySelector("[data-role=status]");
  const volume = root.querySelector("[data-role=volume]");
  const file = root.querySelector("[data-role=file]");
  const pauseButton = root.querySelector("[data-action=pause]");
  const resetButton = root.querySelector("[data-action=reset]");
  const fallback = document.querySelector("[data-role=fallback]");
  const romButtons = Array.from(root.querySelectorAll("[data-rom]"));

  let emulator = null;
  let running = false;
  let loading = null;
  let currentRom = null;

  // Both are set the other way round in the markup, so a browser that cannot
  // run the module shows the fallback instead of dead controls.
  root.hidden = false;
  if (fallback) fallback.hidden = true;

  romButtons.forEach((button) => {
    button.addEventListener("click", () => loadRom(button.dataset.rom, button.dataset.label));
  });

  pauseButton.addEventListener("click", () => (running ? pause() : resume()));

  resetButton.addEventListener("click", () => {
    if (!emulator) return;
    emulator.nes.reloadROM();
    applyVolume();
    resume();
    say("Reset.");
  });

  root.querySelector("[data-action=fullscreen]").addEventListener("click", () => {
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else if (stage.requestFullscreen) {
      stage.requestFullscreen().then(focusStage, () => say("Fullscreen was refused by the browser."));
    }
  });

  volume.addEventListener("input", applyVolume);

  file.addEventListener("change", async () => {
    const chosen = file.files && file.files[0];
    if (!chosen) return;
    try {
      boot(new Uint8Array(await chosen.arrayBuffer()), chosen.name);
    } catch (error) {
      fail(`Could not read ${chosen.name}: ${error.message}`);
    }
    file.value = "";
  });

  // The screen is sized from its container, so it has to be re-fitted whenever
  // the container changes shape.
  window.addEventListener("resize", refit);
  document.addEventListener("fullscreenchange", refit);

  bindTouchControls();
  updateControls();

  async function loadRom(url, label) {
    const request = {};
    loading = request;
    say(`Loading ${label}...`);
    try {
      const response = await fetch(url, { cache: "no-cache" });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }
      const data = new Uint8Array(await response.arrayBuffer());
      if (loading !== request) return; // A later click won the race.
      boot(data, label);
    } catch (error) {
      if (loading !== request) return;
      fail(`Could not load ${label}: ${error.message}`);
    }
  }

  function boot(data, label) {
    loading = null;
    try {
      instance().loadROM(data);
    } catch (error) {
      fail(`${label} did not start: ${error.message}`);
      return;
    }
    currentRom = label;
    running = true;
    overlay.hidden = true;
    applyVolume();
    emulator.resumeAudio();
    refit();
    focusStage();
    say(`${label} is running.`);
    updateControls();
  }

  function instance() {
    if (emulator) return emulator;

    emulator = new Browser({
      container: stage,
      onError: (error) => fail(`Emulation stopped: ${error.message}`),
    });

    // JSNES binds its key handlers to the document, which would swallow the
    // arrow keys everywhere on the page. Move them onto the stage so they only
    // reach the game while it holds focus, and the page still scrolls.
    const keyboard = emulator.keyboard;
    for (const [type, handler] of [
      ["keydown", keyboard.handleKeyDown],
      ["keyup", keyboard.handleKeyUp],
      ["keypress", keyboard.handleKeyPress],
    ]) {
      document.removeEventListener(type, handler);
      stage.addEventListener(type, handler);
    }

    return emulator;
  }

  function pause() {
    if (!emulator || !running) return;
    emulator.stop();
    running = false;
    say(`${currentRom} is paused.`);
    updateControls();
  }

  function resume() {
    if (!emulator || running) return;
    emulator.start();
    emulator.resumeAudio();
    running = true;
    focusStage();
    say(`${currentRom} is running.`);
    updateControls();
  }

  function fail(message) {
    if (emulator) emulator.stop();
    running = false;
    loading = null;
    say(message);
    updateControls();
  }

  function applyVolume() {
    if (!emulator) return;
    const level = Math.round((Number(volume.value) / 100) * MAX_VOLUME);
    emulator.nes.papu.setMasterVolume(level);
  }

  function refit() {
    if (emulator) emulator.fitInParent();
  }

  function focusStage() {
    stage.focus({ preventScroll: true });
  }

  function say(message) {
    status.textContent = message;
  }

  function updateControls() {
    pauseButton.textContent = emulator && !running ? "Resume" : "Pause";
    pauseButton.disabled = !emulator;
    resetButton.disabled = !emulator;
    romButtons.forEach((button) => {
      button.setAttribute("aria-pressed", String(button.dataset.label === currentRom));
    });
  }

  function bindTouchControls() {
    root.querySelectorAll("[data-button]").forEach((key) => {
      const button = PAD[key.dataset.button];

      const press = (event) => {
        if (!emulator) return;
        event.preventDefault();
        if (key.setPointerCapture) key.setPointerCapture(event.pointerId);
        key.classList.add("held");
        emulator.nes.buttonDown(PLAYER_ONE, button);
      };

      const release = (event) => {
        if (!emulator) return;
        event.preventDefault();
        key.classList.remove("held");
        emulator.nes.buttonUp(PLAYER_ONE, button);
      };

      // Pointer capture keeps the release on this element even if the finger
      // slides off it, so a button can never be left stuck down.
      key.addEventListener("pointerdown", press);
      key.addEventListener("pointerup", release);
      key.addEventListener("pointercancel", release);
      key.addEventListener("contextmenu", (event) => event.preventDefault());
    });
  }
}
